// Кейс: .qa/tests/monitoring/MON-036.md шаг 2 · план: .qa/e2e-app/specs/app.md (1.57)
// Pixel на вкладке «ילדים», пока на iPhone идёт и заканчивается мониторинг; затем «בית» → новая строка первой в «ניטורים אחרונים».
// ЗАПУСКАЕТ МОНИТОРИНГ — BANCI_MONITORING=1 + BANCI_ANDROID_SERIAL.
import { assert } from '../../lib/appium.mjs';
import { startMonitoring, endMonitoring, waitTimer } from '../../lib/monitoring.mjs';
import { requireSecondPhone, pixelHome, recentRows, waitNewRow } from '../../lib/second-phone.mjs';

export const name = '«ניטורים אחרונים» на втором телефоне: сеанс закончился, пока Pixel на вкладке «ילדים» → «בית» → новая строка первой #7f31a2 @iphone @app @data';

export default async function (app) {
  const pixel = await requireSecondPhone();
  await pixelHome(pixel);
  const before = await recentRows(pixel);

  await startMonitoring(app);
  await waitTimer(app, 20);
  await pixel.tap('ילדים', { exact: true, what: 'Pixel: вкладка «ילדים»' });
  await endMonitoring(app);

  await pixel.tap('בית', { exact: true, what: 'Pixel: вкладка «בית»' });
  const { rows, row, sec } = await waitNewRow(pixel, before);
  console.log(`     после «בית» новая строка через ${sec.toFixed(1)} с: ${row}`);
  assert(rows[0] === row, `новая строка «${row}» — первая в списке (сейчас сверху: ${rows[0]})`);
}
